package fr.mavoixecrite;
import android.app.*;import android.content.*;import android.os.Looper;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;
import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35})
public class ConversationTest {
 android.content.Context context;
 @Before public void reset(){context=RuntimeEnvironment.getApplication();for(String n:new String[]{DataFile.NAME,DataFile.NAME+".new","phrases-v2.json"})new File(context.getFilesDir(),n).delete();for(String n:new String[]{"draft","voice","MainActivity","conversation","options"})context.getSharedPreferences(n,0).edit().clear().commit();context.getSharedPreferences("options",0).edit().putBoolean("correct",false).commit();}
 AppTest.FakeSpeech fake(MainActivity a){a.speech.close();AppTest.FakeSpeech f=new AppTest.FakeSpeech(a);a.speech=f;return f;}
 void settleUntil(java.util.function.BooleanSupplier condition)throws Exception{long end=System.currentTimeMillis()+10000;while(!condition.getAsBoolean()&&System.currentTimeMillis()<end){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(condition.getAsBoolean());}
 @Test public void typoCorrectedAndUndoRespected()throws Exception{context.getSharedPreferences("options",0).edit().putBoolean("correct",true).commit();try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.FakeSpeech f=fake(a);EditText input=a.findViewById(R.id.message_input);input.setText("bobjour");AppTest.find(a.getWindow().getDecorView(),"Parler").performClick();settleUntil(()->"bonjour".equals(f.spoken));assertEquals("bonjour",input.getText().toString());AppTest.find(a.getWindow().getDecorView(),"Annuler la correction").performClick();assertEquals("bobjour",input.getText().toString());AppTest.find(a.getWindow().getDecorView(),"Parler").performClick();assertEquals("bobjour",f.spoken);}}
 @Test public void correctionCanBeDisabled(){try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.FakeSpeech f=fake(a);((EditText)a.findViewById(R.id.message_input)).setText("bobjour");AppTest.find(a.getWindow().getDecorView(),"Parler").performClick();assertEquals("bobjour",f.spoken);}}
 @Test public void repeatDoesNotReplaceDraft(){try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.FakeSpeech f=fake(a);AppTest.find(a.getWindow().getDecorView(),"Merci").performClick();f.whenStarted.run();EditText input=a.findViewById(R.id.message_input);input.setText("Un autre message");AppTest.find(a.getWindow().getDecorView(),"Répéter").performClick();assertEquals("Merci",f.spoken);assertEquals("Un autre message",input.getText().toString());}}
 @Test public void templateChoiceSpeaksCompletedPhrase()throws Exception{CardStore.Card personal=new CardStore.Card("personal-drink","Besoins","Je voudrais …","chat");personal.choices.add("un verre d’eau");new CardStore(context).save(personal);try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.FakeSpeech f=fake(a);AppTest.find(a.getWindow().getDecorView(),"Besoins").performClick();AppTest.find(a.getWindow().getDecorView(),"Je voudrais …").performClick();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);dialog.getListView().performItemClick(null,0,0);assertEquals("Je voudrais un verre d’eau",f.spoken);}}
 @Test public void newPersonalCaseCanBeCreatedInUi()throws Exception{try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.find(a.getWindow().getDecorView(),"＋ Ajouter une case").performClick();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();Shadows.shadowOf(Looper.getMainLooper()).idle();EditText phrase=findInput(dialog.getWindow().getDecorView());assertNotNull(phrase);phrase.setText("Bonjour Xavier");AppTest.find(dialog.getWindow().getDecorView(),"Garder dans mes favoris").performClick();dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue("La case favorite doit être sauvegardée",new CardStore(context).favorites().stream().anyMatch(x->x.text.equals("Bonjour Xavier")));assertNotNull(AppTest.find(a.getWindow().getDecorView(),"Bonjour Xavier"));}}
 @Test public void favoriteVisibleInOtherFamily()throws Exception{new CardStore(context).favorite("default-0");try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();AppTest.find(a.getWindow().getDecorView(),"Discussion").performClick();assertNotNull(AppTest.find(a.getWindow().getDecorView(),"Oui"));}}
 @Test public void interlocutorReplySurvivesRotation()throws Exception{Intent i=new Intent(context,DisplayActivity.class).putExtra("message",CardStore.DEFAULT_PRESENTATION).putExtra("interlocutor",true);try(ActivityController<DisplayActivity> c=Robolectric.buildActivity(DisplayActivity.class,i).setup()){DisplayActivity a=c.get();TextView message=a.findViewById(R.id.display_message);assertEquals(180f,((View)message.getParent()).getRotation(),0f);AppTest.find(a.getWindow().getDecorView(),"Oui").performClick();assertEquals("Oui",message.getText().toString());c.recreate();assertEquals("Oui",((TextView)c.get().findViewById(R.id.display_message)).getText().toString());assertEquals(1,new PhraseStore(context).history().stream().filter(p->p.text.equals("Oui")).findFirst().get().count);}}
 static EditText findInput(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=findInput(g.getChildAt(i));if(e!=null)return e;}}return null;}
}

